package br.com.sussmartcare.presence.adapters.in.rest; import br.com.sussmartcare.presence.application.*; import br.com.sussmartcare.presence.domain.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*; @RestController @RequestMapping("/api/v1/presence") public class PresenceController { private final PresenceApplicationService app; public PresenceController(PresenceApplicationService a){app=a;} public record PresenceRequest(@NotNull UUID visitId,@NotNull UUID patientId,@NotBlank String eventType,String zoneId,@NotBlank String source,Instant occurredAt){} @PostMapping("/events") public ResponseEntity<PresenceEvent> record(@Valid @RequestBody PresenceRequest r){return ResponseEntity.status(201).body(app.record(r.visitId(),r.patientId(),r.eventType(),r.zoneId(),r.source(),r.occurredAt()));} @GetMapping("/visits/{visitId}") public List<PresenceEvent> history(@PathVariable UUID visitId){return app.history(visitId);} }